style.css:
/* Retro Pac-Man dark blue theme */
body {
  position: relative;
  min-height: 100vh;
  margin: 0;
  background: none;
  overflow: hidden;
  font-family: 'Press Start 2P', monospace, sans-serif; /* optional arcade font */
}

/* Dark blue base background */
body::before {
  content: "";
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: -2;
  background: #0a0f40; /* deep arcade blue */
}

/* Moving dark green dots (Pac-Man pellets) */
body::after {
  content: "";
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: -1;
  pointer-events: none;

  background-image: radial-gradient(circle, #004d00 20%, transparent 21%);
  background-size: 40px 40px; /* grid size */
  background-repeat: repeat;
  animation: pelletScroll 8s linear infinite;
}

/* Animate the pellet grid to scroll */
@keyframes pelletScroll {
  from { background-position: 0 0; }
  to   { background-position: 40px 40px; }
}

/* === TEXT COLORS === */
/* Default black text → white */
body, body * {
  color: #ffffff;
}

/* Links neon cyan for arcade vibe */
a {
  color: #00ffff !important;
}
